      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O FPSO é descrito como unidade flutuante com limitações em condições ambientais severas, apresentando movimentos significativos de roll e pitch e, consequentemente, heave mais crítico que em semissubmersíveis.",
          "trechos": [
            "E7939c73ca7bdc7c1:0:695",
            "E7939c73ca7bdc7c1:695:1385"
          ],
          "condicoes": [
            "aplica-se à comparação geral feita no texto entre FPSO e semissubmersíveis"
