      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "No arranjo em ponto único descrito, todas as linhas convergem para o turret, localizado geralmente na proa, permitindo o giro do navio em torno do sistema de ancoragem e dos risers, enquanto swivels transferem fluidos entre partes estacionária e móvel.",
          "trechos": [
            "E660c5a902b7067d5:0:700"
          ],
          "condicoes": [
            "aplica-se ao FPSO com turret conforme descrito no texto"
