        },
        {
          "proposicao": "Na ancoragem distribuída, os risers são geralmente conectados a um dos bordos, deixando o outro livre para operações de transferência de cargas.",
          "trechos": [
            "E660c5a902b7067d5:700:1399"
          ],
          "condicoes": [
            "aplica-se ao spread mooring conforme descrito no excerto"
